<script setup>
import Errors from '../../Components/Errors.vue';import {ref,watch} from 'vue';import ManagementPager from '../../Components/ManagementPager.vue';import {Head,Link,router} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';import {useI18n} from '../../lib/i18n.js';const props=defineProps({collection:Object,members:Object,filters:Object});const {t}=useI18n(),query=ref(props.filters?.q??'');
const searching=ref(false),searchErrors=ref({});
watch(()=>props.filters?.q,value=>{query.value=value??'';});
function search(){
 if(searching.value)return;
 const q=String(query.value??'').trim();query.value=q;searchErrors.value={};
 router.get(`/collections/${props.collection.id}/progress`,{q},{preserveState:true,replace:true,onStart:()=>{searching.value=true;},onError:errors=>{searchErrors.value=errors;},onFinish:()=>{searching.value=false;}});
}
function clearSearch(){query.value='';search();}
</script><template><Head :title="t('Member progress')"/><AppLayout :title="t('Member progress')" :subtitle="collection.title"><template #actions><Link :href="`/collections/${collection.id}/sharing/members`" class="button secondary">{{t('Manage members')}}</Link></template><p class="notice">{{t('Only current members who agreed to share progress appear here. Personal notes are never shown.')}}</p><Errors :errors="searchErrors"/><form class="panel progress-search" :aria-busy="searching" @submit.prevent="search"><label>{{t('Search accounts by name or email')}}<input v-model="query" type="search" maxlength="100"/></label><button class="button" :disabled="searching">{{t('Search')}}</button><button v-if="query||filters?.q" type="button" class="button secondary" :disabled="searching" @click="clearSearch">{{t('Clear search')}}</button></form><p v-if="!members.data.length" class="panel">{{t(filters?.q?'No accounts match your search.':'No consenting members to show.')}}</p><section v-for="member in members.data" :key="member.id" class="panel progress-member"><h2>{{member.name}}</h2><div class="progress-modes"><article v-for="mode in ['flashcards','study','test']" :key="mode"><h3>{{t(mode==='flashcards'?'Flashcards':mode==='study'?'Study':'Test')}}</h3><dl><dt>{{t('Completed sessions')}}</dt><dd>{{member.summary.modes?.[mode]?.count??0}}</dd><dt>{{t('Words practiced')}}</dt><dd>{{member.summary.modes?.[mode]?.latest_practiced??0}}</dd><dt>{{t('Latest success')}}</dt><dd>{{member.summary.modes?.[mode]?.latest_percent==null?'—':member.summary.modes[mode].latest_percent+'%'}}</dd></dl></article></div></section><ManagementPager :page="members"/></AppLayout></template><style scoped>.progress-member{margin-bottom:20px}.progress-modes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.progress-modes article{padding:16px;background:#eef7f2;border-radius:10px}.progress-modes dd{margin:4px 0 12px;font-weight:700}@media(max-width:600px){.progress-modes{grid-template-columns:1fr}}.progress-search{margin-bottom:20px}@media(max-width:600px){.progress-search .button{width:100%}}.progress-search .button{margin-top:10px}.progress-search .button+.button{margin-left:10px}@media(max-width:600px){.progress-search .button+.button{margin-left:0}}</style>